using BC.FixedAsset.Services;using System;using System.Web.UI.WebControls;namespace BC.FixedAsset.Web.FixedAsset.Review{public partial class FinanceReview:SecurePage{protected GridView gridReview;protected TextBox txtReason;protected HiddenField hidReturnId;protected Button btnReturn;protected Label lblMessage;private readonly AssetSurveyService service=new AssetSurveyService();protected void Page_Load(object s,EventArgs e){if(!IsPostBack)Bind();}private void Bind(){gridReview.DataSource=service.Search("","FinanceReview",AssetAccess,"FinanceReview");gridReview.DataBind();}protected void Grid_RowCommand(object s,GridViewCommandEventArgs e){if(e.CommandName!="ApproveSurvey")return;try{service.Approve(Convert.ToInt64(e.CommandArgument),AssetAccess);Bind();lblMessage.Text="ขึ้นทะเบียนเรียบร้อย";}catch(Exception ex){lblMessage.Text=Server.HtmlEncode(ex.Message);}}protected void Return_Click(object s,EventArgs e){try{long id;if(!long.TryParse(hidReturnId.Value,out id)||string.IsNullOrWhiteSpace(txtReason.Text))throw new ArgumentException("กรุณาระบุเหตุผลสำหรับ Return");service.Return(id,txtReason.Text.Trim(),AssetAccess);hidReturnId.Value="";txtReason.Text="";Bind();lblMessage.Text="Return เรียบร้อย";}catch(Exception ex){lblMessage.Text=Server.HtmlEncode(ex.Message);ClientScript.RegisterStartupScript(GetType(),"returnDialog","document.getElementById('returnDialog').hidden=false;",true);}}}}
